const knownRoute = (pathname: string): boolean => pathname === '/' || pathname === '/health' || pathname === '/api/jobs' || /^\/api\/jobs\/[^/]+$/.test(pathname);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (!knownRoute(pathname)) return send(res, 404, errorBody('not_found', 'Route not found.'));
  const methodAllowed = pathname === '/' ? req.method === 'GET' : pathname === '/api/jobs' ? ['GET', 'POST'].includes(req.method ?? '') : req.method === 'GET';
  if (!methodAllowed) return send(res, 405, errorBody('method_not_allowed', 'Method not allowed.'));
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    const beat = db.prepare('SELECT at FROM worker_heartbeat WHERE id=1').get() as { at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: beat && Date.now() - Number(beat.at) < 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, unknown>[];
    return send(res, 200, { jobs: rows.map(rowToJob) });
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: { field: string; message: string }[] = [];
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push({ field: 'Content-Type', message: 'Must be application/json.' });
    const key = req.headers['idempotency-key'];
    if (Array.isArray(key) || (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, numbers, underscores, or hyphens.' });
    let parsed: unknown;
    try { parsed = JSON.parse(await readBody(req)); } catch { fields.push({ field: 'body', message: 'Must contain valid JSON.' }); }
    const checked = validatePayload(parsed);
    fields.push(...checked.fields);
    if (fields.length) return send(res, 400, errorBody('invalid_request', 'The request is invalid.', fields));
    const payload = checked.payload!;
    const payloadText = JSON.stringify(payload);
    if (typeof key === 'string') {
      const existing = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(key) as { payload: string; job_id: string } | undefined;
      if (existing) {
        if (existing.payload !== payloadText) return send(res, 409, errorBody('idempotency_conflict', 'This key was already used with a different payload.'));
        const job = getJob(existing.job_id);
        if (job) return send(res, 200, job);
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.exec('BEGIN IMMEDIATE');
    try {
      if (typeof key === 'string') {
        const existing = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(key) as { payload: string; job_id: string } | undefined;
        if (existing) {
          db.exec('ROLLBACK');
          if (existing.payload !== payloadText) return send(res, 409, errorBody('idempotency_conflict', 'This key was already used with a different payload.'));
          const job = getJob(existing.job_id);
          return job ? send(res, 200, job) : send(res, 500, errorBody('internal_error', 'Stored job is unavailable.'));
        }
      }
      db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,available_at)
        VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0)`).run(id, payload.input, payload.steps, payload.failAttempts, now, now);
      if (typeof key === 'string') db.prepare('INSERT INTO idempotency (key,payload,job_id) VALUES (?,?,?)').run(key, payloadText, id);
      db.exec('COMMIT');
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    return send(res, 201, getJob(id));
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    let id: string;
    try { id = decodeURIComponent(match[1]!); } catch { return send(res, 404, errorBody('not_found', 'Job not found.')); }
    const job = getJob(id);
    return job ? send(res, 200, job) : send(res, 404, errorBody('not_found', 'Job not found.'));
  }
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown(): void { server.close(() => { db.close(); process.exit(0); }); setTimeout(() => process.exit(1), 5000).unref(); }
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
